effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec2 st = 1.0 / max(acScreenSize, vec2(1.0));
vec4 src = tex(uv);
float rad = dir * 0.017453292519943295;
vec2 d = vec2(cos(rad), sin(rad)) * max(radius, 0.0) * st;
float a = dot(tex(uv - d).rgb, vec3(0.299, 0.587, 0.114));
float b = dot(tex(uv + d).rgb, vec3(0.299, 0.587, 0.114));
float e = clamp(0.5 + (a - b) * depth, 0.0, 1.0);
vec3 c = mix(vec3(e), vec3(e) * tint.rgb * 1.8, tintAmt);
gl_FragColor = vec4(mix(src.rgb, c, mixAmt), src.a);
}
